window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1c7f7496376abb40"]={"versions": [{"id": "FIG-1c7f7496376abb40", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Beispiel- und Werteübersicht (Bitmaskenvergleich) innerhalb der AUTOSAR Classic Platform, spezifisch für das BSW-Modul CanNm (CAN Network Management) im Kontext des Partial Networking (PN). Das Diagramm illustriert die Filterlogik für eingehende NM-PDUs basierend auf einer konfigurierten PN-Filtermaske.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Tabellarische Struktur mit drei Spalten:</p>\n<ul class=\"fig-list\"><li>Filter Mask Value (Byte): Lokale Konfiguration des Steuergeräts mit Maskenwerten je Byte-Index (<code>0x01</code> für Byte 0, <code>0x97</code> für Byte 1).\n</li><li>Compared to received PN info: Byte-Positionen und Werte aus der empfangenen NM-PDU (<code>0x12</code> in NM PDU Byte 4, <code>0x8E</code> in NM PDU Byte 5).\n</li><li>Resulting in: Ergebnis der bitweisen Verknüpfung mit Statusbewertung (<code>0x00 (no relevant PN information)</code>, <code>0x86 (relevant PN information)</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellenkontext ist der Payload-Bereich der empfangenen NM-PDU, in dem die PN-Request-Informationen ab Byte-Offset 4 abgebildet sind.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der bitweisen Filterung:</p>\n<ol class=\"fig-list\"><li>Byte 0 des Filtervektors (<code>0x01</code> = <code>0000 0001b</code>) wird bitweise UND-verknüpft mit Byte 4 der NM-PDU (<code>0x12</code> = <code>0001 0010b</code>). Das Ergebnis ist <code>0x00</code>, womit für dieses Byte keine für das Steuergerät relevanten Partial-Networking-Anforderungen vorliegen.\n</li><li>Byte 1 des Filtervektors (<code>0x97</code> = <code>1001 0111b</code>) wird bitweise UND-verknüpft mit Byte 5 der NM-PDU (<code>0x8E</code> = <code>1000 1110b</code>). Das Ergebnis ist <code>0x86</code> (<code>1000 0110b</code> != 0).\n</li><li>Da mindestens ein Bit im resultierenden Vektor gesetzt ist, erkennt CanNm relevante Partial-Network-Informationen und wertet die PDU als aufweck-/netzwerkrelevant aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informativ/exemplarisch veranschaulichende Tabelle zur Spezifikation des Algorithmus für <code>CanNm_RxIndication</code> bei aktivem Partial Networking (<code>CanNmPnFilterMaskByte</code>). Entwickler müssen beachten, dass der konfigurierte Filtervektor byteweise ab dem festgelegten Offset (<code>CanNmPnInfoOffset</code>, hier beispielhaft Offset 4) auf die Nutzdaten der NM-PDU angewendet wird und eine bitweise logische UND-Operation (<code>PN_Filter_Mask &amp; Rx_PN_Info</code>) erfolgt. Ist das Gesamtergebnis ungleich 0, enthält die NM-PDU relevante PN-Anfragen für die lokale Node.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-deffc3fd3c9cc20e", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Beispiel- und Werteübersicht (Bitmaskenvergleich) innerhalb der AUTOSAR Classic Platform, spezifisch für das BSW-Modul CanNm (CAN Network Management) im Kontext des Partial Networking (PN). Das Diagramm illustriert die Filterlogik für eingehende NM-PDUs basierend auf einer konfigurierten PN-Filtermaske.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Tabellarische Struktur mit drei Spalten:</p>\n<ul class=\"fig-list\"><li>Filter Mask Value (Byte): Lokale Konfiguration des Steuergeräts mit Maskenwerten je Byte-Index (<code>0x01</code> für Byte 0, <code>0x97</code> für Byte 1).\n</li><li>Compared to received PN info: Byte-Positionen und Werte aus der empfangenen NM-PDU (<code>0x12</code> in NM PDU Byte 4, <code>0x8E</code> in NM PDU Byte 5).\n</li><li>Resulting in: Ergebnis der bitweisen Verknüpfung mit Statusbewertung (<code>0x00 (no relevant PN information)</code>, <code>0x86 (relevant PN information)</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellenkontext ist der Payload-Bereich der empfangenen NM-PDU, in dem die PN-Request-Informationen ab Byte-Offset 4 abgebildet sind.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der bitweisen Filterung:</p>\n<ol class=\"fig-list\"><li>Byte 0 des Filtervektors (<code>0x01</code> = <code>0000 0001b</code>) wird bitweise UND-verknüpft mit Byte 4 der NM-PDU (<code>0x12</code> = <code>0001 0010b</code>). Das Ergebnis ist <code>0x00</code>, womit für dieses Byte keine für das Steuergerät relevanten Partial-Networking-Anforderungen vorliegen.\n</li><li>Byte 1 des Filtervektors (<code>0x97</code> = <code>1001 0111b</code>) wird bitweise UND-verknüpft mit Byte 5 der NM-PDU (<code>0x8E</code> = <code>1000 1110b</code>). Das Ergebnis ist <code>0x86</code> (<code>1000 0110b</code> != 0).\n</li><li>Da mindestens ein Bit im resultierenden Vektor gesetzt ist, erkennt CanNm relevante Partial-Network-Informationen und wertet die PDU als aufweck-/netzwerkrelevant aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informativ/exemplarisch veranschaulichende Tabelle zur Spezifikation des Algorithmus für <code>CanNm_RxIndication</code> bei aktivem Partial Networking (<code>CanNmPnFilterMaskByte</code>). Entwickler müssen beachten, dass der konfigurierte Filtervektor byteweise ab dem festgelegten Offset (<code>CanNmPnInfoOffset</code>, hier beispielhaft Offset 4) auf die Nutzdaten der NM-PDU angewendet wird und eine bitweise logische UND-Operation (<code>PN_Filter_Mask &amp; Rx_PN_Info</code>) erfolgt. Ist das Gesamtergebnis ungleich 0, enthält die NM-PDU relevante PN-Anfragen für die lokale Node.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-48f29f98b18ea17a", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Beispiel- und Werteübersicht (Bitmaskenvergleich) innerhalb der AUTOSAR Classic Platform, spezifisch für das BSW-Modul CanNm (CAN Network Management) im Kontext des Partial Networking (PN). Das Diagramm illustriert die Filterlogik für eingehende NM-PDUs basierend auf einer konfigurierten PN-Filtermaske.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Tabellarische Struktur mit drei Spalten:</p>\n<ul class=\"fig-list\"><li>Filter Mask Value (Byte): Lokale Konfiguration des Steuergeräts mit Maskenwerten je Byte-Index (<code>0x01</code> für Byte 0, <code>0x97</code> für Byte 1).\n</li><li>Compared to received PN info: Byte-Positionen und Werte aus der empfangenen NM-PDU (<code>0x12</code> in NM PDU Byte 4, <code>0x8E</code> in NM PDU Byte 5).\n</li><li>Resulting in: Ergebnis der bitweisen Verknüpfung mit Statusbewertung (<code>0x00 (no relevant PN information)</code>, <code>0x86 (relevant PN information)</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellenkontext ist der Payload-Bereich der empfangenen NM-PDU, in dem die PN-Request-Informationen ab Byte-Offset 4 abgebildet sind.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der bitweisen Filterung:</p>\n<ol class=\"fig-list\"><li>Byte 0 des Filtervektors (<code>0x01</code> = <code>0000 0001b</code>) wird bitweise UND-verknüpft mit Byte 4 der NM-PDU (<code>0x12</code> = <code>0001 0010b</code>). Das Ergebnis ist <code>0x00</code>, womit für dieses Byte keine für das Steuergerät relevanten Partial-Networking-Anforderungen vorliegen.\n</li><li>Byte 1 des Filtervektors (<code>0x97</code> = <code>1001 0111b</code>) wird bitweise UND-verknüpft mit Byte 5 der NM-PDU (<code>0x8E</code> = <code>1000 1110b</code>). Das Ergebnis ist <code>0x86</code> (<code>1000 0110b</code> != 0).\n</li><li>Da mindestens ein Bit im resultierenden Vektor gesetzt ist, erkennt CanNm relevante Partial-Network-Informationen und wertet die PDU als aufweck-/netzwerkrelevant aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informativ/exemplarisch veranschaulichende Tabelle zur Spezifikation des Algorithmus für <code>CanNm_RxIndication</code> bei aktivem Partial Networking (<code>CanNmPnFilterMaskByte</code>). Entwickler müssen beachten, dass der konfigurierte Filtervektor byteweise ab dem festgelegten Offset (<code>CanNmPnInfoOffset</code>, hier beispielhaft Offset 4) auf die Nutzdaten der NM-PDU angewendet wird und eine bitweise logische UND-Operation (<code>PN_Filter_Mask &amp; Rx_PN_Info</code>) erfolgt. Ist das Gesamtergebnis ungleich 0, enthält die NM-PDU relevante PN-Anfragen für die lokale Node.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f21628dad7c2ced7", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Beispiel- und Werteübersicht (Bitmaskenvergleich) innerhalb der AUTOSAR Classic Platform, spezifisch für das BSW-Modul CanNm (CAN Network Management) im Kontext des Partial Networking (PN). Das Diagramm illustriert die Filterlogik für eingehende NM-PDUs basierend auf einer konfigurierten PN-Filtermaske.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Tabellarische Struktur mit drei Spalten:</p>\n<ul class=\"fig-list\"><li>Filter Mask Value (Byte): Lokale Konfiguration des Steuergeräts mit Maskenwerten je Byte-Index (<code>0x01</code> für Byte 0, <code>0x97</code> für Byte 1).\n</li><li>Compared to received PN info: Byte-Positionen und Werte aus der empfangenen NM-PDU (<code>0x12</code> in NM PDU Byte 4, <code>0x8E</code> in NM PDU Byte 5).\n</li><li>Resulting in: Ergebnis der bitweisen Verknüpfung mit Statusbewertung (<code>0x00 (no relevant PN information)</code>, <code>0x86 (relevant PN information)</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellenkontext ist der Payload-Bereich der empfangenen NM-PDU, in dem die PN-Request-Informationen ab Byte-Offset 4 abgebildet sind.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf der bitweisen Filterung:</p>\n<ol class=\"fig-list\"><li>Byte 0 des Filtervektors (<code>0x01</code> = <code>0000 0001b</code>) wird bitweise UND-verknüpft mit Byte 4 der NM-PDU (<code>0x12</code> = <code>0001 0010b</code>). Das Ergebnis ist <code>0x00</code>, womit für dieses Byte keine für das Steuergerät relevanten Partial-Networking-Anforderungen vorliegen.\n</li><li>Byte 1 des Filtervektors (<code>0x97</code> = <code>1001 0111b</code>) wird bitweise UND-verknüpft mit Byte 5 der NM-PDU (<code>0x8E</code> = <code>1000 1110b</code>). Das Ergebnis ist <code>0x86</code> (<code>1000 0110b</code> != 0).\n</li><li>Da mindestens ein Bit im resultierenden Vektor gesetzt ist, erkennt CanNm relevante Partial-Network-Informationen und wertet die PDU als aufweck-/netzwerkrelevant aus.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Informativ/exemplarisch veranschaulichende Tabelle zur Spezifikation des Algorithmus für <code>CanNm_RxIndication</code> bei aktivem Partial Networking (<code>CanNmPnFilterMaskByte</code>). Entwickler müssen beachten, dass der konfigurierte Filtervektor byteweise ab dem festgelegten Offset (<code>CanNmPnInfoOffset</code>, hier beispielhaft Offset 4) auf die Nutzdaten der NM-PDU angewendet wird und eine bitweise logische UND-Operation (<code>PN_Filter_Mask &amp; Rx_PN_Info</code>) erfolgt. Ist das Gesamtergebnis ungleich 0, enthält die NM-PDU relevante PN-Anfragen für die lokale Node.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1c7f7496376abb40", "to": "FIG-deffc3fd3c9cc20e", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-deffc3fd3c9cc20e", "to": "FIG-48f29f98b18ea17a", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-48f29f98b18ea17a", "to": "FIG-f21628dad7c2ced7", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
